import { createRequire } from 'node:module';
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(`console: ${m.text()}`); });
await page.goto('http://127.0.0.1:4173', { waitUntil: 'load' });
await page.waitForTimeout(1400);
const screen = async path => {
  const session = await page.context().newCDPSession(page);
  const { data } = await session.send('Page.captureScreenshot', { format: 'jpeg', quality: 82, fromSurface: true, captureBeyondViewport: false });
  writeFileSync(path, Buffer.from(data, 'base64'));
  await session.detach();
};
const visible = async id => await page.locator(`#${id}`).evaluate(e => getComputedStyle(e).display !== 'none');
console.log('title:', await page.title(), 'menu:', await visible('main-menu'), 'canvas:', await page.locator('#game').evaluate(c => [c.width,c.height]));
await screen('/tmp/opencode/facility-menu.jpg');
await page.locator('[data-action=settings]').click();
console.log('settings visible:', await visible('settings-screen'));
await page.locator('[data-lang=en]').click();
console.log('language button selected:', await page.locator('[data-lang=en]').getAttribute('class'));
await page.locator('#subtitle-toggle').click();
console.log('subtitle toggle:', await page.locator('#subtitle-toggle').textContent());
await page.locator('[data-action=back]').click();
await page.locator('[data-action=credits]').click();
console.log('archive visible:', await visible('archive-screen'));
await page.locator('[data-action=back]').click();
await page.locator('[data-action=lobby]').click();
console.log('lobby visible:', await visible('lobby-screen'));
await page.locator('[data-action=offline]').click();
console.log('room visible:', await visible('room-screen'), 'room code:', await page.locator('#room-code').textContent());
await page.locator('#fill-bots').click();
console.log('bot status:', await page.locator('#lobby-status').textContent());
await page.locator('[data-action=launch]').click();
await page.waitForTimeout(900);
console.log('game active:', await page.locator('#game-ui').evaluate(e => e.classList.contains('active')), 'objective:', await page.locator('#objective-text').textContent());
await page.keyboard.press('Escape');
console.log('pause visible:', await page.locator('#pause-screen').evaluate(e => e.classList.contains('show')));
await page.locator('[data-action=resume]').click();
console.log('resume visible:', await page.locator('#pause-screen').evaluate(e => e.classList.contains('show')));
await page.keyboard.press('j');
console.log('objective log open:', await page.locator('#objective-log').evaluate(e => e.classList.contains('open')));
await page.keyboard.press('j');
await page.waitForTimeout(250);
await screen('/tmp/opencode/facility-play.jpg');
console.log('page errors:', errors);
await browser.close();

